#!/usr/bin/env python3
# Generated by scripts/build-skill.mjs from scripts/skill/check_cast.py in the drawcast repository (github.com/hmelberg/drawcast). Do not edit by hand: rebuild with `npm run build:skill`.
"""Check a drawcast before giving its link: the problems the player would skip.

    python3 check_cast.py cast.yaml       -> "OK ..." (exit 0) or the problems (exit 1)
    python3 check_cast.py < cast.yaml

The Python twin of check_cast.mjs, for a sandbox with Python and no Node
(ChatGPT, the Gemini app, and others). check_cast.mjs is drawcast's own
validator; this one checks against the same schema the skill ships
(references/schema.json) plus the commonest mistakes the schema alone does not
catch: a repeated id, a command naming an element that does not exist, an
arrow end written as [x, y]. When both are at hand, prefer check_cast.mjs.

Python 3.8+ standard library, and PyYAML to read YAML (most sandboxes have it;
a drawcast written as JSON needs nothing more).
"""
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
SCHEMA_PATH = os.path.join(HERE, "..", "references", "schema.json")

# A drawcast's settings at its top (lang, voices, tags …): the app reads them before
# the schema sees the drawing, so the schema does not list them. The same words as
# make_link's SETTING_RE (drawcast src/spec/script/detect.ts).
SETTINGS = ("lang", "voice", "level", "record", "feedback", "affirm", "heading", "page", "canvas", "domain", "vars", "text",
            "zoom_from", "book", "style", "credits", "board", "use", "with", "adjust", "details", "sources", "more", "end_page",
            "role", "chapter", "subtitle", "advance", "gap", "transitions", "next", "enroll", "prompt", "comments", "views",
            "poster", "tags", "format", "thumb", "voices", "teaches")

# The commands that name elements by id, and where (drawcast's verbs; a list or one id).
ID_FIELDS = ("draw", "erase", "highlight", "point", "focus", "move", "animate", "show", "hide", "clear", "keep", "glow", "pulse")


def load_text(text):
    """The documents in `text`: YAML (one or several, `---` between) or JSON."""
    try:
        return [json.loads(text)]
    except ValueError:
        pass
    try:
        import yaml
    except ImportError:
        raise SystemExit("PyYAML is not installed here: install it (pip install pyyaml) or write the drawcast as JSON.")
    return [d for d in yaml.safe_load_all(text) if d is not None]


def specs_of(docs):
    """The drawable specs: a spec with elements/commands or a template, or each item of a playlist."""
    out = []
    for doc in docs:
        if not isinstance(doc, dict):
            continue
        if "audio" in doc and len(doc) <= 2:
            continue  # recorded narration, not a drawing
        items = doc.get("items")
        if isinstance(items, list):
            for item in items:
                spec = item.get("spec", item) if isinstance(item, dict) else None
                if isinstance(spec, dict):
                    out.append(spec)
            continue
        if any(k in doc for k in ("elements", "commands", "template")):
            out.append(doc)
    return out


# ---- a small JSON Schema validator for the keywords schema.json uses -------------------

TYPES = {
    "object": lambda v: isinstance(v, dict),
    "array": lambda v: isinstance(v, list),
    "string": lambda v: isinstance(v, str),
    "number": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    "integer": lambda v: (isinstance(v, int) and not isinstance(v, bool)) or (isinstance(v, float) and v.is_integer()),
    "boolean": lambda v: isinstance(v, bool),
    "null": lambda v: v is None,
}


class Validator:
    def __init__(self, schema):
        self.root = schema

    def resolve(self, ref):
        node = self.root
        for part in ref.lstrip("#/").split("/"):
            node = node[part.replace("~1", "/").replace("~0", "~")]
        return node

    def errors(self, inst, schema, path):
        """Every problem with `inst` against `schema`, as (path, message)."""
        if schema is True or schema is None:
            return []
        if schema is False:
            return [(path, "is not allowed here")]
        if "$ref" in schema:
            return self.errors(inst, self.resolve(schema["$ref"]), path) + self.errors(inst, {k: v for k, v in schema.items() if k != "$ref"}, path)
        out = []
        t = schema.get("type")
        if t == "array" and isinstance(inst, str) and isinstance(schema.get("items"), dict) and schema["items"].get("type") == "string":
            # A single id where a list of ids goes: the app wraps it itself ("target: dot" is "target: [dot]").
            inst = [inst]
        if t is not None:
            kinds = t if isinstance(t, list) else [t]
            if not any(TYPES.get(k, lambda v: True)(inst) for k in kinds):
                return [(path, "must be %s, not %s" % (" or ".join(kinds), type_name(inst)))]
        if "const" in schema and inst != schema["const"]:
            out.append((path, "must be %s" % json.dumps(schema["const"])))
        if "enum" in schema and inst not in schema["enum"]:
            out.append((path, "must be one of %s" % ", ".join(json.dumps(e) for e in schema["enum"][:12])))
        if isinstance(inst, str):
            if "minLength" in schema and len(inst) < schema["minLength"]:
                out.append((path, "is too short"))
            if "maxLength" in schema and len(inst) > schema["maxLength"]:
                out.append((path, "is longer than %d characters" % schema["maxLength"]))
            if "pattern" in schema and not re.search(schema["pattern"], inst):
                out.append((path, "does not match %s" % schema["pattern"]))
        if TYPES["number"](inst):
            if "minimum" in schema and inst < schema["minimum"]:
                out.append((path, "must be at least %s" % schema["minimum"]))
            if "maximum" in schema and inst > schema["maximum"]:
                out.append((path, "must be at most %s" % schema["maximum"]))
            if "exclusiveMinimum" in schema and inst <= schema["exclusiveMinimum"]:
                out.append((path, "must be more than %s" % schema["exclusiveMinimum"]))
        if isinstance(inst, list):
            if "minItems" in schema and len(inst) < schema["minItems"]:
                out.append((path, "needs at least %d items" % schema["minItems"]))
            if "maxItems" in schema and len(inst) > schema["maxItems"]:
                out.append((path, "has more than %d items" % schema["maxItems"]))
            items = schema.get("items")
            if isinstance(items, dict):
                for i, v in enumerate(inst):
                    out += self.errors(v, items, "%s[%d]" % (path, i))
        if isinstance(inst, dict):
            props = schema.get("properties", {})
            for key in schema.get("required", []):
                if key not in inst:
                    out.append((path, 'needs the field "%s"' % key))
            for key, v in inst.items():
                if key in props:
                    out += self.errors(v, props[key], "%s.%s" % (path, key) if path else key)
                elif schema.get("additionalProperties") is False:
                    out.append((path, 'has no field "%s" — it does not exist; look it up in references/schema.json' % key))
                elif isinstance(schema.get("additionalProperties"), dict):
                    out += self.errors(v, schema["additionalProperties"], "%s.%s" % (path, key) if path else key)
        for sub in schema.get("allOf", []):
            out += self.errors(inst, sub, path)
        for key in ("oneOf", "anyOf"):
            if key in schema:
                out += self.choice(inst, schema[key], path, key)
        return out

    def choice(self, inst, branches, path, key):
        """oneOf/anyOf: no problems when a branch fits (oneOf: exactly one); else the
        problems of the branch meant — the one whose `type` matches the element's."""
        results = [self.errors(inst, b, path) for b in branches]
        fitting = sum(1 for r in results if not r)
        if fitting == 1 or (fitting > 1 and key == "anyOf"):
            return []
        if fitting > 1:
            return []  # several fit: the app tells them apart by more than the schema says
        if isinstance(inst, dict) and isinstance(inst.get("type"), str):
            for b, r in zip(branches, results):
                if self.type_const(b) == inst["type"]:
                    return r
            known = sorted(filter(None, (self.type_const(b) for b in branches)))
            if known:
                return [(path, 'type "%s" does not exist; the types are: %s' % (inst["type"], ", ".join(known)))]
        best = min(results, key=len)
        return best if len(best) <= 3 else [(path, "does not match any allowed shape (%s)" % "; ".join(m for _, m in best[:2]))]

    def type_const(self, branch):
        if "$ref" in branch:
            branch = self.resolve(branch["$ref"])
        t = branch.get("properties", {}).get("type", {}) if isinstance(branch, dict) else {}
        if "const" in t:
            return t["const"]
        if isinstance(t.get("enum"), list) and len(t["enum"]) == 1:
            return t["enum"][0]
        return None


def type_name(v):
    for name in ("boolean", "integer", "number", "string", "array", "object", "null"):
        if TYPES[name](v):
            return name
    return type(v).__name__


# ---- what the schema alone does not say ------------------------------------------------

def semantic_problems(spec):
    out = []
    elements = spec.get("elements") if isinstance(spec.get("elements"), list) else []
    ids = {}
    for i, el in enumerate(elements):
        if not isinstance(el, dict):
            continue
        eid = el.get("id")
        if isinstance(eid, str):
            if eid in ids:
                out.append('element "%s": the id is used twice' % eid)
            ids[eid] = el
        if el.get("type") == "arrow":
            for end in ("from", "to"):
                v = el.get(end)
                if isinstance(v, list) or TYPES["number"](v):
                    out.append('element "%s" (arrow): %s must be {x: …, y: …} or {ref: <id>, anchor: …}, not %s' % (eid, end, json.dumps(v)))
    # Ids are given anywhere: in `elements`, and in commands that bring new pieces in.
    known = set(all_ids(spec))
    for i, cmd in enumerate(spec.get("commands") or []):
        if not isinstance(cmd, dict):
            continue
        for field in ID_FIELDS:
            v = cmd.get(field)
            names = v if isinstance(v, list) else [v] if isinstance(v, str) else []
            for name in names:
                base = name.split(".", 1)[0] if isinstance(name, str) else name
                # Parts the app names after their element: an element's label is label_<id>, a
                # paper's quote <id>_quote, a morph's steps <id>_2 … Not an error: a warning to look at.
                derived = isinstance(base, str) and (
                    (base.startswith("label_") and base[6:] in known) or any(base.startswith(k + "_") for k in known))
                if isinstance(base, str) and known and base not in known and not derived and not spec.get("template"):
                    out.append('warning: command #%d %s: no element "%s" — check the id' % (i + 1, field, name))
    return out


def all_ids(node):
    if isinstance(node, dict):
        if isinstance(node.get("id"), str):
            yield node["id"]
        for v in node.values():
            yield from all_ids(v)
    elif isinstance(node, list):
        for v in node:
            yield from all_ids(v)


def spoken(spec):
    return sum(1 for c in spec.get("commands") or [] if isinstance(c, dict) and isinstance(c.get("speak"), str) and c["speak"].strip())


def check(text, schema):
    docs = load_text(text)
    specs = specs_of(docs)
    if not specs:
        return False, 0, ["No drawable item: the file has no `elements`/`commands` (or `template`), nor a playlist of them."]
    v = Validator(schema)
    problems = []
    for n, spec in enumerate(specs):
        where = "item %d: " % (n + 1) if len(specs) > 1 else ""
        top = {k: val for k, val in spec.items() if k not in SETTINGS or k in schema.get("properties", {})}
        for path, msg in v.errors(top, schema, ""):
            problems.append("%s%s %s" % (where, readable(path, spec), msg))
        problems += [("warning: " + where + p[len("warning: "):]) if p.startswith("warning: ") else where + p for p in semantic_problems(spec)]
    seen, unique = set(), []
    for p in problems:
        if p not in seen:
            seen.add(p)
            unique.append(p)
    return not any(not p.startswith("warning: ") for p in unique), sum(spoken(s) for s in specs), unique


def readable(path, spec):
    """elements[3].style -> element "beam" (arrow) style."""
    m = re.match(r"^elements\[(\d+)\](.*)$", path)
    if m:
        els = spec.get("elements") or []
        el = els[int(m.group(1))] if int(m.group(1)) < len(els) else {}
        name = 'element "%s"' % el.get("id") if isinstance(el, dict) and el.get("id") else "element #%d" % (int(m.group(1)) + 1)
        if isinstance(el, dict) and isinstance(el.get("type"), str):
            name += " (%s)" % el["type"]
        rest = m.group(2).lstrip(".")
        return "%s%s" % (name, " " + rest if rest else "") + ":"
    m = re.match(r"^commands\[(\d+)\](.*)$", path)
    if m:
        rest = m.group(2).lstrip(".")
        return "command #%d%s:" % (int(m.group(1)) + 1, " " + rest if rest else "")
    return (path or "the drawcast") + ":"


def main(argv):
    files = [a for a in argv if not a.startswith("--")]
    text = open(files[0], encoding="utf-8-sig").read() if files else sys.stdin.read()
    with open(SCHEMA_PATH, encoding="utf-8") as f:
        schema = json.load(f)
    ok, lines, problems = check(text, schema)
    if ok:
        print("OK — %d spoken lines" % lines)
        for p in problems:
            print(p)
        return 0
    print("NOT VALID — the player would skip or refuse these; fix every one, then check again:")
    for p in problems:
        print(("  " if p.startswith("warning: ") else "- ") + p)
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
